/**
 * Release signing for the sideloaded APK (Part 17). `android/` is regenerated by prebuild, so the
 * signing config is injected here. The upload keystore and its passwords live outside the repo,
 * in `~/.gradle/gradle.properties`:
 *
 *   BETADVISOR_UPLOAD_STORE_FILE=/absolute/path/betadvisor-upload.jks
 *   BETADVISOR_UPLOAD_STORE_PASSWORD=...
 *   BETADVISOR_UPLOAD_KEY_ALIAS=betadvisor-upload
 *   BETADVISOR_UPLOAD_KEY_PASSWORD=...
 *
 * Without them, packaging a release fails loudly instead of silently signing with the debug key.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// betadvisor: release signing';

const SIGNING_CONFIG = `
        ${MARKER}
        if (findProperty('BETADVISOR_UPLOAD_STORE_FILE')) {
            release {
                storeFile file(findProperty('BETADVISOR_UPLOAD_STORE_FILE'))
                storePassword findProperty('BETADVISOR_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('BETADVISOR_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('BETADVISOR_UPLOAD_KEY_PASSWORD')
            }
        }`;

const GUARD = `
${MARKER}: refuse to package a release without the upload key.
gradle.taskGraph.whenReady { graph ->
    def packagesRelease = graph.allTasks.any { it.name ==~ /(package|assemble|bundle)Release/ }
    if (packagesRelease && !findProperty('BETADVISOR_UPLOAD_STORE_FILE')) {
        throw new GradleException('Release signing is not configured: set BETADVISOR_UPLOAD_* in ~/.gradle/gradle.properties (see app/plugins/withReleaseSigning.js)')
    }
}
`;

function applySigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  const withConfig = gradle.replace(/signingConfigs \{\n/, (m) => `${m}${SIGNING_CONFIG}\n`);
  const releaseBlock =
    /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (withConfig === gradle || !releaseBlock.test(withConfig)) {
    throw new Error('withReleaseSigning: android/app/build.gradle has an unexpected layout');
  }
  const withRelease = withConfig.replace(
    releaseBlock,
    `$1signingConfig findProperty('BETADVISOR_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`,
  );
  return `${withRelease}\n${GUARD}`;
}

const withReleaseSigning = (config) =>
  withAppBuildGradle(config, (c) => {
    c.modResults.contents = applySigning(c.modResults.contents);
    return c;
  });

module.exports = withReleaseSigning;
module.exports.applySigning = applySigning;
